//! Differential tool-scenario fixture for ledger C05/H08.
//!
//! `c_tools-evidence.json` is generated by `tests/c_tools-reference.mjs`, which runs
//! the same scripted tool scenarios through the unchanged Pi 1.3.0 reference (with
//! the pinned `pi-cursor-sdk` adapter) and through the rpi retained worker (packaged
//! `runtime/main.mjs`) driven over its real peer protocol. This test compares the
//! complete count objects for every scenario and pins the C05/H08 execution counts:
//! one Cursor native tool, one bridge execution, zero replay executions.
use serde_json::{json, Value};

const EVIDENCE: &str = include_str!("c_tools-evidence.json");

fn evidence() -> Value {
    serde_json::from_str(EVIDENCE).expect("c_tools-evidence.json is valid JSON")
}

fn scenarios(evidence: &Value) -> &Vec<Value> {
    evidence["scenarios"]
        .as_array()
        .expect("evidence scenarios is an array")
}

fn scenario<'a>(evidence: &'a Value, name: &str) -> &'a Value {
    scenarios(evidence)
        .iter()
        .find(|scenario| scenario["name"] == name)
        .unwrap_or_else(|| panic!("scenario {name} missing from evidence"))
}

#[test]
fn every_tool_scenario_agrees_between_reference_and_rpi_worker() {
    let evidence = evidence();
    assert_eq!(evidence["status"], "pass");
    assert_eq!(evidence["schema"], "rpi-cursor-c-tools-evidence/1");
    assert_eq!(evidence["runtime"]["node"], "24.22.0");
    assert_eq!(evidence["provenance"]["piVersion"], "1.3.0");
    assert_eq!(evidence["provenance"]["cursorSdkVersion"], "1.0.37");
    assert_eq!(evidence["provenance"]["piCursorSdkVersion"], "0.5.3");
    let scenarios = scenarios(&evidence);
    assert_eq!(scenarios.len(), 5);
    for scenario in scenarios {
        assert_eq!(scenario["status"], "pass", "{}", scenario["name"]);
        assert!(
            scenario["problems"].as_array().unwrap().is_empty(),
            "{}",
            scenario["name"]
        );
        assert_eq!(scenario["determinism"]["reference"], true, "{}", scenario["name"]);
        assert_eq!(scenario["determinism"]["candidate"], true, "{}", scenario["name"]);
        // Complete value comparison: both runtimes and the declared expectation.
        assert_eq!(
            scenario["reference"], scenario["candidate"],
            "reference and candidate counts differ for {}",
            scenario["name"]
        );
        assert_eq!(
            scenario["reference"], scenario["expect"],
            "observed counts differ from the expectation for {}",
            scenario["name"]
        );
    }
}

#[test]
fn c05_h08_exact_execution_counts_are_one_cursor_one_bridge_zero_replay() {
    let evidence = evidence();
    let turn = scenario(&evidence, "tool-turn");
    // One Cursor native tool call.
    assert_eq!(turn["reference"]["nativeToolCalls"], json!({"shell": 1}));
    // One Pi tool executed through the MCP bridge.
    assert_eq!(turn["reference"]["bridgeToolExecutions"], 1);
    // The host is asked to run the bridge tool and the replayed native tool exactly once each.
    assert_eq!(turn["reference"]["hostToolInvocations"], json!({"bash": 1, "fake_echo": 1}));
    // Recorded activity never executes work.
    assert_eq!(turn["reference"]["replayToolExecutions"], 0);
    assert_eq!(turn["reference"]["violations"], 0);
    assert_eq!(turn["reference"], turn["candidate"]);
}

#[test]
fn rpi_worker_publishes_inert_recorded_bindings() {
    let evidence = evidence();
    // The worker publishes eight host bindings: the replay-only activity tool is a
    // `recorded` binding and every native Cursor tool carries the replay prefix.
    let turn = scenario(&evidence, "tool-turn");
    let bindings = &turn["candidateDetail"]["recordedBindings"];
    assert_eq!(bindings["cursor"], "recorded");
    for name in ["read", "bash", "edit", "write", "grep", "find", "ls"] {
        assert_eq!(bindings[name], "builtin", "binding for {name}");
    }
    let prefixes = turn["candidateDetail"]["recordedPrefixes"].as_object().unwrap();
    assert_eq!(prefixes.len(), 8);
    for (name, prefix) in prefixes {
        assert_eq!(prefix, "cursor-replay-", "replay prefix for {name}");
    }
}

#[test]
fn recorded_activity_stays_inert_on_both_runtimes() {
    let evidence = evidence();
    for scenario in scenarios(&evidence) {
        assert_eq!(
            scenario["reference"]["replayToolExecutions"], 0,
            "{}",
            scenario["name"]
        );
        assert_eq!(
            scenario["candidate"]["replayToolExecutions"], 0,
            "{}",
            scenario["name"]
        );
    }
    // An incomplete native tool surfaces as a single replay-only activity card and
    // performs no work on either runtime.
    let incomplete = scenario(&evidence, "incomplete-native");
    assert_eq!(incomplete["reference"]["nativeToolCalls"], json!({"shell": 1}));
    assert_eq!(incomplete["reference"]["hostToolInvocations"], json!({"cursor": 1}));
    assert_eq!(incomplete["reference"]["bridgeToolExecutions"], 0);
    assert_eq!(incomplete["candidate"], incomplete["reference"]);
    // A native-only turn replays the recorded shell result without executing it.
    let native = scenario(&evidence, "native-only");
    assert_eq!(native["reference"]["hostToolInvocations"], json!({"bash": 1}));
    assert_eq!(native["reference"]["bridgeToolExecutions"], 0);
    // A bridge-only turn executes exactly one Pi tool and no Cursor native tool.
    let bridge = scenario(&evidence, "bridge-only");
    assert_eq!(bridge["reference"]["hostToolInvocations"], json!({"fake_echo": 1}));
    assert_eq!(bridge["reference"]["nativeToolCalls"], json!({}));
    assert_eq!(bridge["reference"]["bridgeToolExecutions"], 1);
    // A failing bridge tool is executed once and surfaces one tool-level failure.
    let failure = scenario(&evidence, "bridge-failure");
    assert_eq!(failure["reference"]["bridgeToolExecutions"], 1);
    assert_eq!(failure["reference"]["bridgeToolFailures"], 1);
    assert_eq!(failure["reference"]["hostToolInvocations"], json!({"fake_fail": 1}));
    assert_eq!(failure["reference"]["replayToolExecutions"], 0);
    assert_eq!(failure["candidate"], failure["reference"]);
}
